<?php
declare(strict_types=1); require_once __DIR__.'/../includes/auth_check.php'; require_once __DIR__.'/../includes/functions.php';
$id=0;$editing=false;$book=['isbn'=>'','title'=>'','category_id'=>'','publisher_id'=>'','year_published'=>'','total_copies'=>1,'available_copies'=>1];$selected=[];
if($editing){$st=$pdo->prepare('SELECT * FROM books WHERE book_id=?');$st->execute([$id]);$book=$st->fetch();if(!$book){set_flash('error','Book not found.');redirect('/books/index.php');}$st=$pdo->prepare('SELECT author_id FROM book_authors WHERE book_id=?');$st->execute([$id]);$selected=array_column($st->fetchAll(),'author_id');}
$categories=$pdo->query('SELECT category_id,category_name FROM categories ORDER BY category_name')->fetchAll();$publishers=$pdo->query('SELECT publisher_id,publisher_name FROM publishers ORDER BY publisher_name')->fetchAll();$authors=$pdo->query('SELECT author_id,author_name FROM authors ORDER BY author_name')->fetchAll();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf_token($_POST['csrf_token']??null)){$error='Session expired. Refresh and try again.';}else{$isbn=trim($_POST['isbn']??'');$title=trim($_POST['title']??'');$cat=(int)($_POST['category_id']??0);$pub=($_POST['publisher_id']??'')!==''?(int)$_POST['publisher_id']:null;$year=($_POST['year_published']??'')!==''?(int)$_POST['year_published']:null;$total=(int)($_POST['total_copies']??0);$available=(int)($_POST['available_copies']??0);$selected=array_map('intval',$_POST['authors']??[]);if($isbn===''||$title===''||$cat<1||$total<1||$available<0||$available>$total||($year!==null&&($year<1000||$year>date('Y')+1))){$error='Enter valid book details. Available copies must be between zero and total copies.';}else{try{$pdo->beginTransaction();if($editing){$st=$pdo->prepare('UPDATE books SET isbn=?,title=?,category_id=?,publisher_id=?,year_published=?,total_copies=?,available_copies=? WHERE book_id=?');$st->execute([$isbn,$title,$cat,$pub,$year,$total,$available,$id]);$pdo->prepare('DELETE FROM book_authors WHERE book_id=?')->execute([$id]);}else{$st=$pdo->prepare('INSERT INTO books(isbn,title,category_id,publisher_id,year_published,total_copies,available_copies) VALUES(?,?,?,?,?,?,?)');$st->execute([$isbn,$title,$cat,$pub,$year,$total,$available]);$id=(int)$pdo->lastInsertId();} $ins=$pdo->prepare('INSERT INTO book_authors(book_id,author_id) VALUES(?,?)');foreach(array_unique($selected) as $aid){$ins->execute([$id,$aid]);}$pdo->commit();set_flash('success',$editing?'Book updated.':'Book added.');redirect('/books/index.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof PDOException&&$e->getCode()==='23000'?'That ISBN is already registered or a selected record is invalid.':'Unable to save the book. Check the details and try again.';}}}}
$pageTitle=$editing?'Edit book':'Add book';$activePage='books';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/navbar.php';?>
<main class="main-content"><header class="topbar"><div><span class="eyebrow">LIBRARY CATALOGUE</span><h1><?=e($pageTitle)?></h1></div></header><section class="content-card"><div class="section-heading"><div><h2><?=e($pageTitle)?></h2><p>Fields marked with * are required.</p></div><a class="btn btn-secondary" href="index.php">Back to books</a></div><?php if($error): ?><div class="alert error"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field"><label>ISBN *</label><input name="isbn" required maxlength="20" value="<?=e($_POST['isbn']??$book['isbn'])?>"></div><div class="field"><label>Book title *</label><input name="title" required maxlength="200" value="<?=e($_POST['title']??$book['title'])?>"></div><div class="field"><label>Category *</label><select name="category_id" required><option value="">Select category</option><?php foreach($categories as $c): ?><option value="<?=$c['category_id']?>" <?=((string)($_POST['category_id']??$book['category_id'])===(string)$c['category_id'])?'selected':''?>><?=e($c['category_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Publisher</label><select name="publisher_id"><option value="">Unknown / not recorded</option><?php foreach($publishers as $p): ?><option value="<?=$p['publisher_id']?>" <?=((string)($_POST['publisher_id']??$book['publisher_id'])===(string)$p['publisher_id'])?'selected':''?>><?=e($p['publisher_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Year published</label><input type="number" name="year_published" min="1000" max="<?=date('Y')+1?>" value="<?=e($_POST['year_published']??$book['year_published'])?>"></div><div class="field"><label>Total copies *</label><input type="number" name="total_copies" min="1" required value="<?=e($_POST['total_copies']??$book['total_copies'])?>"></div><div class="field"><label>Available copies *</label><input type="number" name="available_copies" min="0" required value="<?=e($_POST['available_copies']??$book['available_copies'])?>"></div><div class="field"><label>Authors (hold Ctrl to select multiple)</label><select name="authors[]" multiple size="5"><?php foreach($authors as $a): ?><option value="<?=$a['author_id']?>" <?=in_array((int)$a['author_id'],$selected,true)?'selected':''?>><?=e($a['author_name'])?></option><?php endforeach;?></select></div></div><div class="form-actions"><button class="btn">Save book</button><a class="btn btn-secondary" href="index.php">Cancel</a></div></form></section></main><?php require __DIR__.'/../includes/footer.php';?>